// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { ArrayLike } from '@stdlib/types/array';
import { OutputPolicy, DataType, typedndarray } from '@stdlib/types/ndarray';

/**
* Output array.
*/
type OutputArray<T> = typedndarray<T>;

/**
* Input array.
*/
type InputArray<U> = typedndarray<U>;

/**
* Interface defining "base" options.
*/
interface BaseOptions {
	/**
	* List of dimensions over which to perform an operation.
	*/
	dims?: ArrayLike<number>;
}

/**
* Interface defining constructor options.
*/
interface ConstructorOptions {
	/**
	* Boolean specifying whether the order of element traversal must match the memory layout of an input ndarray.
	*/
	strictTraversalOrder?: boolean;
}

/**
* Strided function.
*
* @param arrays - output ndarray
* @param options - function options
* @returns result
*/
type Nullary<T> = ( arrays: [ typedndarray<T> ], options?: unknown ) => typedndarray<T>;

/**
* Strided function.
*
* @param arrays - output ndarrays
* @param options - function options
* @returns result
*/
type NullaryWithAdditionalArrays<T> = ( arrays: [ typedndarray<T>, ...Array<typedndarray<T>> ], options?: unknown ) => typedndarray<T>;

/**
* Base dispatch table.
*/
interface BaseDispatchTable<T> {
	/**
	* Default strided function.
	*/
	default: Nullary<T> | NullaryWithAdditionalArrays<T>;
}

/**
* Dispatch table.
*/
interface DispatchTable<T> extends BaseDispatchTable<T> {
	/**
	* One-dimensional list of ndarray data types describing specialized output ndarray argument signatures.
	*/
	types: ArrayLike<DataType>;

	/**
	* List of strided functions which are specific to specialized output ndarray argument signatures.
	*/
	fcns: ArrayLike<Nullary<T> | NullaryWithAdditionalArrays<T>>;
}

/**
* Dispatch policies.
*/
interface Policies {
	/**
	* Output data type policy.
	*/
	output: OutputPolicy;
}

/**
* Class for applying a strided function to an output ndarray.
*/
declare class NullaryStrided1dDispatch<T> {
	/**
	* Constructor for applying a strided function to an output ndarray.
	*
	* @param table - dispatch table
	* @param odtypes - list containing lists of supported output data types for each ndarray argument
	* @param policies - dispatch policies
	* @param options - function options
	* @returns instance
	*
	* @example
	* var base = require( '@stdlib/blas/ext/base/ndarray/gsorthp' );
	* var dtypes = require( '@stdlib/ndarray/dtypes' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	* var ndarray = require( '@stdlib/ndarray/base/ctor' );
	*
	* var odt = dtypes( 'all' );
	* var policies = {
	*     'output': 'same'
	* };
	*
	* var table = {
	*     'default': base
	* };
	* var sorthp = new NullaryStrided1dDispatch( table, [ odt ], policies );
	*
	* var xbuf = [ -1.0, 2.0, -3.0 ];
	* var x = new ndarray( 'generic', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
	*
	* var o = scalar2ndarray( 1.0, {
	*      'dtype': 'generic'
	* });
	*
	* var out = sorthp.assign( x, o );
	* // returns <ndarray>
	*
	* var arr = ndarray2array( x );
	* // returns [ -3.0, -1.0, 2.0 ]
	*
	* var bool = ( out === x );
	* // returns true
	*/
	constructor( table: DispatchTable<T> | BaseDispatchTable<T>, odtypes: ArrayLike<ArrayLike<DataType>>, policies: Policies, options?: ConstructorOptions );

	/**
	* Applies a strided function and assigns results to a provided output ndarray.
	*
	* @param x - output ndarray
	* @param options - function options
	* @returns output ndarray
	*
	* @example
	* var base = require( '@stdlib/blas/ext/base/ndarray/sorthp' );
	* var dtypes = require( '@stdlib/ndarray/dtypes' );
	* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	* var ndarray = require( '@stdlib/ndarray/base/ctor' );
	*
	* var odt = dtypes( 'all' );
	* var policies = {
	*     'output': 'same'
	* };
	*
	* var table = {
	*     'default': base
	* };
	* var sorthp = new NullaryStrided1dDispatch( table, [ odt ], policies );
	*
	* var xbuf = [ -1.0, 2.0, -3.0 ];
	* var x = new ndarray( 'generic', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
	*
	* var o = scalar2ndarray( 1.0, {
	*     'dtype': 'generic'
	* });
	*
	* var out = sorthp.assign( x, o );
	* // returns <ndarray>
	*
	* var arr = ndarray2array( x );
	* // returns [ -3.0, -1.0, 2.0 ]
	*
	* var bool = ( out === x );
	* // returns true
	*/
	assign<U extends OutputArray<T> = OutputArray<T>>( x: U, options?: BaseOptions ): U;

	/**
	* Applies a strided function and assigns results to a provided output ndarray.
	*
	* @param x - output ndarray
	* @param o - additional ndarray argument
	* @param args - output ndarray, additional ndarray arguments, and function options
	* @returns output ndarray
	*
	* @example
	* var base = require( '@stdlib/blas/ext/base/ndarray/sorthp' );
	* var dtypes = require( '@stdlib/ndarray/dtypes' );
	* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	* var ndarray = require( '@stdlib/ndarray/base/ctor' );
	*
	* var odt = dtypes( 'all' );
	* var policies = {
	*     'output': 'same'
	* };
	*
	* var table = {
	*     'default': base
	* };
	* var sorthp = new NullaryStrided1dDispatch( table, [ odt ], policies );
	*
	* var xbuf = [ -1.0, 2.0, -3.0 ];
	* var x = new ndarray( 'generic', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
	*
	* var o = scalar2ndarray( 1.0, {
	*     'dtype': 'generic'
	* });
	*
	* var out = sorthp.assign( x, o );
	* // returns <ndarray>
	*
	* var arr = ndarray2array( x );
	* // returns [ -3.0, -1.0, 2.0 ]
	*
	* var bool = ( out === x );
	* // returns true
	*/
	assign<U extends OutputArray<T> = OutputArray<T>, V = unknown>( x: U, y: InputArray<V> | U, ...args: Array<InputArray<V> | U | BaseOptions> ): U;
}

/**
* Interface defining a constructor which is both "newable" and "callable".
*/
interface NullaryStrided1dDispatchConstructor {
	/**
	* Constructor for applying a strided function to an output ndarray.
	*
	* @param table - dispatch table
	* @param odtypes - list containing lists of supported output data types for each ndarray argument
	* @param policies - dispatch policies
	* @param options - function options
	* @returns instance
	*
	* @example
	* var base = require( '@stdlib/blas/ext/base/ndarray/sorthp' );
	* var dtypes = require( '@stdlib/ndarray/dtypes' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	* var ndarray = require( '@stdlib/ndarray/base/ctor' );
	*
	* var odt = dtypes( 'all' );
	* var policies = {
	*     'output': 'same'
	* };
	*
	* var table = {
	*     'default': base
	* };
	* var sorthp = new NullaryStrided1dDispatch( table, [ odt ], policies );
	*
	* var xbuf = [ -1.0, 2.0, -3.0 ];
	* var x = new ndarray( 'generic', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
	*
	* var o = scalar2ndarray( 1.0, {
	*      'dtype': 'generic'
	* });
	*
	* var out = sorthp.assign( x, o );
	* // returns <ndarray>
	*
	* var arr = ndarray2array( x );
	* // returns [ -3.0, -1.0, 2.0 ]
	*
	* var bool = ( out === x );
	* // returns true
	*/
	new<T = unknown>( table: DispatchTable<T> | BaseDispatchTable<T>, odtypes: ArrayLike<ArrayLike<DataType>>, policies: Policies, options?: ConstructorOptions ): NullaryStrided1dDispatch<T>;

	/**
	* Constructor for applying a strided function to an output ndarray.
	*
	* @param table - dispatch table
	* @param odtypes - list containing lists of supported output data types for each ndarray argument
	* @param policies - dispatch policies
	* @param options - function options
	* @returns instance
	*
	* @example
	* var base = require( '@stdlib/blas/ext/base/ndarray/sorthp' );
	* var dtypes = require( '@stdlib/ndarray/dtypes' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	* var ndarray = require( '@stdlib/ndarray/base/ctor' );
	*
	* var odt = dtypes( 'all' );
	* var policies = {
	*     'output': 'same'
	* };
	*
	* var table = {
	*     'default': base
	* };
	* var sorthp = new NullaryStrided1dDispatch( table, [ odt ], policies );
	*
	* var xbuf = [ -1.0, 2.0, -3.0 ];
	* var x = new ndarray( 'generic', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
	*
	* var o = scalar2ndarray( 1.0, {
	*      'dtype': 'generic'
	* });
	*
	* var out = sorthp.assign( x );
	* // returns <ndarray>
	*
	* var arr = ndarray2array( x );
	* // returns [ -3.0, -1.0, 2.0 ]
	*
	* var bool = ( out === x );
	* // returns true
	*/
	<T = unknown>( table: DispatchTable<T> | BaseDispatchTable<T>, odtypes: ArrayLike<ArrayLike<DataType>>, policies: Policies, options?: ConstructorOptions ): NullaryStrided1dDispatch<T>;
}

/**
* Constructor for applying a strided function to an output ndarray.
*
* @param table - dispatch table
* @param odtypes - list containing lists of supported input data types for each ndarray argument
* @param policies - dispatch policies
* @param options - function options
* @returns instance
*
* @example
* var base = require( '@stdlib/blas/ext/base/ndarray/sorthp' );
* var dtypes = require( '@stdlib/ndarray/dtypes' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray2array = require( '@stdlib/ndarray/to-array' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
*
* var odt = dtypes( 'all' );
* var policies = {
*     'output': 'same'
* };
*
* var table = {
*     'default': base
* };
* var sorthp = new NullaryStrided1dDispatch( table, [ odt ], policies );
*
* var xbuf = [ -1.0, 2.0, -3.0 ];
* var x = new ndarray( 'generic', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
*
* var o = scalar2ndarray( 1.0, {
*      'dtype': 'generic'
* });
*
* var y = sorthp.assign( x, o );
* // returns <ndarray>
*
* var arr = ndarray2array( y );
* // returns [ -1.0, 2.0, 2.0 ]
*/
declare var ctor: NullaryStrided1dDispatchConstructor;


// EXPORTS //

export = ctor;
